"""현행 r03 후보5개 카탈로그. prepare_candidates.py는 과거 r02 재현 전용."""
from pathlib import Path
import json,hashlib
root=Path(__file__).resolve().parents[2];base=root/'_workspace/pebble-yoyo'
rows=[]
for c in ['ja-hyun','nabi']:
 for mode in ['ground','air']:
  folder=base/'motions'/c/mode/'r03';m=json.loads((folder/'candidate.json').read_text());png=str((folder/'sheet-128.png').relative_to(root));tres=folder/'candidate.tres'
  parts=['[gd_resource type="SpriteFrames" load_steps=18 format=3]',f'[ext_resource type="Texture2D" path="res://{png}" id="1"]']
  for i in range(16):parts.append(f'[sub_resource type="AtlasTexture" id="frame_{i}"]\natlas = ExtResource("1")\nregion = Rect2({i%8*128}, {i//8*128}, 128, 128)')
  frames=',\n'.join('{"duration": '+str(d)+', "texture": SubResource("frame_'+str(i)+'")}' for i,d in enumerate(m['frame_durations']))
  parts.append('[resource]\nanimations = [{"frames": ['+frames+'], "loop": false, "name": &"'+m['motion_id']+'", "speed": 60.0}]')
  tres.write_text('\n\n'.join(parts)+'\n')
  rows.append({'asset_id':c+'-'+m['motion_id'].replace('_','-')+'-candidate-r03','type':'animation-candidate','character_id':c,'visual_state_id':m['motion_id'],'path':png,'sha256':m['sheet_sha256'],'sprite_frames_path':'res://'+str(tres.relative_to(root)),'fps':60,'loop':False,'frame_count':16,'atlas_columns':8,'cell_size':128,'frame_durations':m['frame_durations'],'equipment_phase_frame_ranges':m['equipment_phase_frame_ranges'],'frame_anchors':m['frame_anchors'],'foot_pivot_y':m['foot_pivot_y'],'presentation_scale':m['presentation_scale'],'expected_action':('지상 발 디딤을 유지하며' if mode=='ground' else '공중에 무릎을 접은 채')+' 팔을 준비하고 전방으로 요요를 던져18틱 동안 늘린 뒤18틱 동안 회수하고 전투 자세로 복귀한다. 실·요요는 별도 표시하고 손 연결·좌우 반전·몸 크기를 유지한다.','action_source':'docs/gameplay/pebble-yoyo.md','equipment_resource_path':'assets/loadouts/pebble_yoyo_accessory.tres','reference_set':m['reference_set'],'reference_attachments':m['reference_attachments'],'comparison_references':m.get('comparison_references',[]),'source_path':m['source_path'],'source_paths':[m['source_path']]+[e['source_path'] for e in m.get('whole_figure_boundary_endpoints',[])],'source_sha256':m['source_sha256'],'conversion':{'method':'uniform whole-figure source packing plus approved whole idle entry/recovery pose; no part edits','uniform_scale':m['common_scale'],'packing':m['packing'],'whole_figure_boundary_endpoints':m.get('whole_figure_boundary_endpoints',[]),'size_basis':m['size_basis']},'rights':{'status':'derivative of approved character appearance; candidate requires explicit user motion adoption','references':['docs/contracts/character-appearance-v01.json','docs/content/motion-action-review.md','_workspace/pebble-yoyo/05_revision_request.md']},'creation':{'method':'built-in image_gen with approved runtime idle/jump and v01 references attached','provider':'OpenAI built-in image generation','version':'pebble-yoyo-r03','reference_attachments':m['reference_attachments']}})
# Fifth candidate: exact approved idle pixels/time; body-root drawing correction only.
import copy, shutil
approved=next(a for a in json.loads((root/'assets/character/manifest.json').read_text())['assets'] if a.get('type')=='animation-runtime' and a.get('character_id')=='nabi' and a.get('visual_state_id')=='idle')
folder=base/'motions/nabi/idle/r03';folder.mkdir(parents=True,exist_ok=True)
shutil.copy2(root/approved['path'],folder/'sheet-128.png')
tres=folder/'candidate.tres';original_tres=root/approved['sprite_frames_path'].removeprefix('res://');tres.write_text(original_tres.read_text().replace('res://'+approved['path'],'res://'+str((folder/'sheet-128.png').relative_to(root))))
# Manual two-shoe-centre measurements at alpha>100 in y110..127, preserving idle0.
sole_midpoints=[82.,71.5,60.,49.5,83.,72.5,62.,52.5,82.,73.,62.5,52.5,82.,73.,62.5,54.5]
anchors=[{'body_root':[64.+x-sole_midpoints[0],float(approved['foot_pivot_y'])]} for x in sole_midpoints]
row=copy.deepcopy(approved)
row.update({'type':'animation-candidate','asset_id':'nabi-idle-body-root-candidate-r03','path':str((folder/'sheet-128.png').relative_to(root)),'sprite_frames_path':'res://'+str(tres.relative_to(root)),'layout_only_from_asset_id':approved['asset_id'],'frame_anchors':anchors,'expected_action':'기존 승인 대기의 모든 그림·순서·시간·그림 픽셀을 유지하며 양발의 중점을 frame0과 같은 화면 위치에 고정한다. 네 열마다 약10px씩 미끄러지던 표시를 body_root 앵커만으로 보정하여 장비 진입과 복귀 위치를 잇는다.','action_source':'docs/content/motion-action-review.md','source_path':approved['path'],'source_sha256':approved['sha256'],'source_paths':[approved['path']],'creation':{'method':'exact approved PNG bytes and SpriteFrames frame/time reuse; drawing body_root metadata only','provider':'project-local deterministic metadata','version':'pebble-yoyo-idle-root-r03'},'rights':{'status':'existing approved art reused unchanged; new body_root layout requires explicit user adoption','references':['docs/contracts/character-appearance-v01.json','_workspace/pebble-yoyo/05_revision_request.md']},'conversion':{'method':'PNG bytes unchanged; only frame body_root anchors correct horizontal drawing drift; source idle frame0 position retained','two_shoe_midpoint_pixels':sole_midpoints,'target_midpoint_pixels':sole_midpoints[0]}})
(folder/'candidate.json').write_text(json.dumps(row,ensure_ascii=False,indent=2)+'\n');rows.append(row)
catalog={'schema_version':1,'kind':'motion-candidates','approval_status':'pending','assets':rows,'attack_sources':['assets/combat/movesets/two_fighter_ja_hyun_moveset.tres','assets/combat/movesets/two_fighter_nabi_moveset.tres','assets/loadouts/pebble_yoyo_accessory.tres'],'character_movesets':{'ja-hyun':'assets/combat/movesets/two_fighter_ja_hyun_moveset.tres','nabi':'assets/combat/movesets/two_fighter_nabi_moveset.tres'}}
p=base/'candidate-catalog.json';p.write_text(json.dumps(catalog,ensure_ascii=False,indent=2)+'\n')
(base/'candidate-scope.json').write_text(json.dumps({'schema_version':1,'kind':'candidate-motion-review','catalog_sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'motions':[{'character_id':r['character_id'],'motion':r['visual_state_id']} for r in rows]},ensure_ascii=False,indent=2)+'\n')
print('Prepared private candidate catalog/scope and5 review-only SpriteFrames.')
